const HOOKS = {
  PreToolUse: { script: '.claude/hooks/pre-tool-use.js', tools: ['Bash', 'PowerShell'], failClosed: true },
  PostToolUse: { script: '.claude/hooks/post-tool-use.js', tools: ['Write', 'Edit', 'MultiEdit', 'Bash', 'PowerShell'], failClosed: false },
