function matcherCovers(matcher, tool) {
  if (matcher === undefined || matcher === '' || matcher === '*') return true;
  try {
    return new RegExp(`^(?:${matcher})$`).test(tool);
  } catch {
    return false;
  }
}

function hookScript(hook) {
  const m = Array.isArray(hook.args) && hook.args.length === 1 ? SCRIPT_ARG.exec(String(hook.args[0])) : null;
  return m ? m[1] : null;
}

function checkHookHandler(file, event, spec, hook) {
  const where = `${event} hook`;
  if (hook.type !== 'command') add('ERROR', file, `${where}: type must be "command".`);
  if (hook.command !== 'node') add('ERROR', file, `${where}: use exec form — command "node" with the script in args (found command ${JSON.stringify(hook.command)}).`);
  const script = hookScript(hook);
  if (!script) {
    add('ERROR', file, `${where}: args must be exactly ["\${CLAUDE_PROJECT_DIR}/.claude/hooks/<script>.js"] (found ${JSON.stringify(hook.args)}).`);
  } else if (!common.exists(script)) {
    add('ERROR', file, `${where}: script missing: ${script}`);
  }
  if (spec.failClosed && hook.onFailure !== 'block') {
    add('ERROR', file, `${where}: critical pre-tool enforcement must fail closed (onFailure: "block").`);
  }
  if (!spec.failClosed && hook.onFailure !== undefined) {
    add('ERROR', file, `${where}: onFailure is reserved for the critical PreToolUse enforcement; post-change and Stop hooks report failures visibly without blocking (on Stop it has no effect).`);
  }
}

function checkSettings() {
  const file = '.claude/settings.json';
  if (!common.exists(file)) {
    add('ERROR', file, 'settings file missing.');
    return;
  }
  let settings;
  try {
    settings = JSON.parse(common.readText(file));
  } catch (e) {
    add('ERROR', file, `invalid JSON: ${e.message}`);
    return;
  }
  const hooks = settings.hooks || {};
  for (const event of Object.keys(hooks)) if (!HOOKS[event]) add('ERROR', file, `unexpected hook event: ${event}`);
  for (const [event, spec] of Object.entries(HOOKS)) {
    const groups = Array.isArray(hooks[event]) ? hooks[event] : [];
    const handlers = groups.flatMap((group) => (Array.isArray(group.hooks) ? group.hooks : []).map((hook) => ({ group, hook })));
    for (const { hook } of handlers) checkHookHandler(file, event, spec, hook);
    const own = handlers.filter(({ hook }) => hookScript(hook) === spec.script);
    if (!own.length) {
      add('ERROR', file, `${event} does not run ${spec.script}.`);
      continue;
    }
    for (const tool of spec.tools || []) {
      if (!own.some(({ group }) => matcherCovers(group.matcher, tool))) add('ERROR', file, `${event} matcher does not cover the ${tool} tool.`);
    }
  }
}

